// 派单148切片2：只对合成目录/主库做受控操作，不启动Agent/读真实配置/凭据/会话。
import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import {join,dirname} from 'node:path';import {fileURLToPath} from 'node:url';
import {createAgentWrite} from '../server/agent-write.mjs';import {openRepository,digest} from '../server/repository.mjs';import {seed,makeAsset,current} from '../src/store.js';import {readLocalSkill} from '../server/skill-files.mjs';
const fixtureRoot=process.env.AGENT_WRITE_FIXTURE_ROOT||join(import.meta.dirname,'../outputs/synthetic-agent-write-tests');
const identity=s=>[s.dev,s.ino,s.birthtimeMs,s.uid,s.size,s.mtimeMs].join(':');const homeIdentity=s=>[s.dev,s.ino,s.birthtimeMs,s.uid].join(':');
async function fixture(t,{enabled=true,filesystem=fs,checkMetadata=async()=>{},checkConfigMetadata=async()=>null}={}){
 await fs.mkdir(fixtureRoot,{recursive:true,mode:0o700});const base=await fs.realpath(await fs.mkdtemp(join(fixtureRoot,'fixture-'))),repository=await openRepository(join(base,'database'));
 const homes={codex:join(base,'合成Codex家目录'),hermes:join(base,'合成Hermes家目录')};for(const h of Object.values(homes)){await fs.mkdir(join(h,'skills'),{recursive:true,mode:0o700});await fs.chmod(h,0o700);}
 const sourceText='---\nname: local-example\ndescription: 合成\n---\n# 保留原文\n';const from=join(homes.codex,'skills','local-example');await fs.mkdir(join(from,'assets'),{recursive:true,mode:0o755});await fs.writeFile(join(from,'SKILL.md'),sourceText,{mode:0o644});await fs.writeFile(join(from,'assets','raw.bin'),new Uint8Array([0,128,255]),{mode:0o644});await fs.writeFile(join(from,'run.sh'),'#!/bin/sh\nprintf synthetic\n',{mode:0o755});await fs.chmod(join(from,'run.sh'),0o755);
 const hermesSkill=join(homes.hermes,'skills','hermes-example');await fs.mkdir(hermesSkill,{mode:0o755});await fs.writeFile(join(hermesSkill,'SKILL.md'),'# 合成Hermes副本\n',{mode:0o644});
 const configText='# 中文保留\napi_key="SYNTHETIC_SECRET_DO_NOT_LEAK"\n[tui]\nanimations=true\n[plugins."review@synthetic"]\nenabled = true # 原注释\n[[skills.config]]\npath = '+JSON.stringify(join(from,'SKILL.md'))+'\nenabled = true\n';const configPath=join(homes.codex,'config.toml');await fs.writeFile(configPath,configText,{mode:0o600});await fs.writeFile(join(homes.hermes,'config.yaml'),'display:\n  show_reasoning: true\n',{mode:0o600});
 const asset=makeAsset({type:'Skill',title:'合成固定版本',files:[{path:'source',directory:true,text:false,data:new Uint8Array(),mode:0o755},{path:'source/SKILL.md',text:true,data:'---\nname: published-example\n---\n# 固定版本\n',mode:0o644},{path:'source/assets',directory:true,text:false,data:new Uint8Array(),mode:0o755},{path:'source/assets/binary.bin',text:false,data:new Uint8Array([1,254,0]),mode:0o644},{path:'source/run.sh',text:true,data:'#!/bin/sh\nprintf never-execute\n',mode:0o755}]});
 await repository.write({...seed(),assets:[asset]},{initialize:true});const targets=[];for(const agentId of ['codex','hermes']){const program=join(base,agentId+'-synthetic-cli');await fs.writeFile(program,'SYNTHETIC NEVER EXECUTE',{mode:0o600});targets.push({schema:1,id:'target-'+agentId,bindingId:'binding-'+agentId,agentId,label:'合成 '+agentId,program:{path:program,kind:'CLI'},home:{id:'home-'+agentId,path:homes[agentId],label:'合成Home'},createdAt:'2026-10-04T00:00:00.000Z',updatedAt:'2026-10-04T00:00:00.000Z'});}
 await repository.updateConnections(c=>({roots:[],projects:[],agents:[],github:{status:'not_connected',login:'',message:'',at:''},projectScannedAt:'',agentScannedAt:'',errors:[],truncated:false,...c,agentTargets:targets}));const adapters={checkConfigMetadata,inspectAgentInventory:async agentId=>({errors:[],truncated:false,homes:[{id:'home-'+agentId,path:homes[agentId],source:'合成独立目录',status:'present',errors:[],identity:homeIdentity(await fs.lstat(homes[agentId]))}]}),inspectAgentPrograms:async(agentId)=>[{...targets.find(t=>t.agentId===agentId).program,status:'present',identity:identity(await fs.lstat(targets.find(t=>t.agentId===agentId).program.path))}]};
 const setting={enabled,generation:0,options:{}},settings={get:async name=>{assert.equal(name,'agent');return{...setting};},assertEnabled:async name=>{assert.equal(name,'agent');if(!setting.enabled)throw Object.assign(new Error('Agent 写入默认关闭'),{status:409});}};let now=Date.parse('2026-10-04T00:00:00.000Z');const manager=createAgentWrite(repository,{settings,adapters,clock:()=>now,filesystem,checkMetadata});
 t.after(async()=>{await repository.close();await fs.rm(base,{recursive:true,force:true});});return{base,repository,homes,targets,from,hermesSkill,asset,sourceText,configText,configPath,manager,adapters,settings,setting,advance(ms){now+=ms;},recreate(options={}){return createAgentWrite(repository,{settings,adapters,clock:()=>now,checkMetadata,...options});},async revision(){return(await repository.read()).revision;},async publish(targetId='target-codex'){return manager.publishPreview({targetId,assetId:asset.id,versionId:current(asset).id,revision:await this.revision()});}};
}
const confirm=p=>({token:p.token,revision:p.revision});
const pluginItem=async f=>(await f.manager.inspect({targetId:'target-codex'})).items.find(i=>i.type==='Plugin');
const localItem=async(f,targetId='target-codex')=>(await f.manager.inspect({targetId})).items.find(i=>i.type==='Skill'&&i.enabled!==false);

test('默认关工厂零IO；关态预览可以回读但apply拒绝写',async t=>{let called=0;const filesystem=new Proxy(fs,{get(o,k){if(typeof o[k]!=='function')return o[k];return()=>{called++;throw new Error('should not run');};}});createAgentWrite({directory:'/synthetic-unused'},{filesystem});assert.equal(called,0);const f=await fixture(t,{enabled:false}),p=await f.publish();await assert.rejects(f.manager.apply(confirm(p)),e=>e.operationNotStarted===true);assert.equal(await fs.readFile(f.configPath,'utf8'),f.configText);assert.equal((await f.manager.history({targetId:'target-codex'})).items.length,0);});
test('官方登记Codex插件/Skill启停只改boolean，备份不含全文凭据，中文路径逆补丁可回滚',async t=>{const f=await fixture(t);for(const item of [await pluginItem(f),await localItem(f)]){const before=await fs.readFile(f.configPath,'utf8'),p=await f.manager.togglePreview({targetId:'target-codex',itemId:item.id,enabled:false,revision:await f.revision()});assert.equal(JSON.stringify(p).includes('SYNTHETIC_SECRET'),false);assert.equal(await fs.readFile(f.configPath,'utf8'),before);const result=await f.manager.apply(confirm(p));assert.equal(result.status,'matches_after');assert.equal(result.adoption,'unverified');const after=await fs.readFile(f.configPath,'utf8');assert.equal(after.replace('enabled = false','enabled = true'),before);const record=await fs.readFile(join(f.repository.directory,'agent-content-config',p.token+'.json'),'utf8');assert.equal(record.includes('SYNTHETIC_SECRET'),false);const restore=await f.manager.rollbackPreview({id:p.token,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(restore))).status,'matches_after');assert.equal(await fs.readFile(f.configPath,'utf8'),before);}});
test('Codex未登记独立Skill的未知状态不猜默认；新增正式表可逐字回滚',async t=>{const f=await fixture(t);await fs.writeFile(f.configPath,'# 合成中文\napi_key="SYNTHETIC_SECRET_DO_NOT_LEAK"\n',{mode:0o600});const item=await localItem(f);assert.equal(item.enabled,null);const before=await fs.readFile(f.configPath,'utf8'),p=await f.manager.togglePreview({targetId:'target-codex',itemId:item.id,enabled:false,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');const restore=await f.manager.rollbackPreview({id:p.token,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(restore))).status,'matches_after');assert.equal(await fs.readFile(f.configPath,'utf8'),before);});
test('无Skill根时已登记插件仍可独立官方配置启停',async t=>{const f=await fixture(t);await fs.rm(join(f.homes.codex,'skills'),{recursive:true});const item=await pluginItem(f);assert.ok(item);const p=await f.manager.togglePreview({targetId:'target-codex',itemId:item.id,enabled:false,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');});
test('Hermes独立目录停用留全副本；回读/恢复完整指纹与mode，源主库不改变',async t=>{const f=await fixture(t),before=(await readLocalSkill([join(f.homes.hermes,'skills')],f.hermesSkill)).fingerprint,item=await localItem(f,'target-hermes'),state=await f.repository.read(),p=await f.manager.togglePreview({targetId:'target-hermes',itemId:item.id,enabled:false,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');await assert.rejects(fs.lstat(f.hermesSkill),{code:'ENOENT'});const backup=join(f.homes.hermes,'skills.disabled','.workbench-'+p.token,'hermes-example');assert.equal((await readLocalSkill([dirname(backup)],backup)).fingerprint,before);const restore=await f.manager.rollbackPreview({id:p.token,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(restore))).status,'matches_after');assert.equal((await readLocalSkill([join(f.homes.hermes,'skills')],f.hermesSkill)).fingerprint,before);assert.deepEqual(await f.repository.read(),state);});
test('发布固定完整Skill版本：二进制/执行权限保留，不安装不运行；回滚副本仍保留',async t=>{const f=await fixture(t),state=await f.repository.read(),p=await f.publish();assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');const to=join(f.homes.codex,'skills','published-example');assert.deepEqual([...await fs.readFile(join(to,'assets','binary.bin'))],[1,254,0]);assert.equal((await fs.lstat(join(to,'run.sh'))).mode&0o777,0o755);assert.equal((await fs.lstat(to)).mode&0o777,0o700);const restore=await f.manager.rollbackPreview({id:p.token,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(restore))).status,'matches_after');const backup=join(f.homes.codex,'skills.disabled','.workbench-'+restore.token,'published-example');assert.equal((await fs.readFile(join(backup,'SKILL.md'),'utf8')).includes('固定版本'),true);assert.deepEqual(await f.repository.read(),state);});
test('Skill跨Agent等价目录迁移，源原文指纹不变；不搬Home配置',async t=>{const f=await fixture(t),item=await localItem(f),before=(await readLocalSkill([join(f.homes.codex,'skills')],f.from)).fingerprint,p=await f.manager.migrationPreview({sourceTargetId:'target-codex',targetId:'target-hermes',itemId:item.id,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');assert.equal((await readLocalSkill([join(f.homes.codex,'skills')],f.from)).fingerprint,before);assert.equal((await readLocalSkill([join(f.homes.hermes,'skills')],join(f.homes.hermes,'skills','local-example'))).fingerprint,before);assert.equal(await fs.readFile(join(f.homes.hermes,'config.yaml'),'utf8'),'display:\n  show_reasoning: true\n');await assert.rejects(f.manager.configMigrationPreview({sourceTargetId:'target-codex',targetId:'target-hermes',key:'tui.animations',revision:await f.revision()}),/没有已证实的等价/);});
test('开关generation/TTL/主库/程序身份漂移拒绝写入，重复与重启只回读不重放',async t=>{const f=await fixture(t);let p=await f.publish();f.setting.generation++;await assert.rejects(f.manager.apply(confirm(p)),e=>e.status===409&&e.operationNotStarted===true);p=await f.publish();f.advance(300001);await assert.rejects(f.manager.apply(confirm(p)),/过期/);p=await f.publish();await f.repository.updateConnections(c=>({...c}));await assert.rejects(f.manager.apply(confirm(p)),/主库/);p=await f.publish();await fs.appendFile(f.targets[0].program.path,'changed');await assert.rejects(f.manager.apply(confirm(p)),/身份已变化/);p=await f.publish();assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');const after=await fs.lstat(join(f.homes.codex,'skills','published-example'));assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');assert.equal((await f.recreate().apply(confirm(p))).status,'matches_after');assert.equal((await fs.lstat(join(f.homes.codex,'skills','published-example'))).ino,after.ino);});
test('源或目标外部变化拒绝覆盖；回滚位置冲突保留两侧',async t=>{const f=await fixture(t),p=await f.publish();assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');await fs.appendFile(join(f.homes.codex,'skills','published-example','SKILL.md'),'外部改动');assert.equal((await f.manager.check({id:p.token})).status,'changed');await assert.rejects(f.manager.rollbackPreview({id:p.token,revision:await f.revision()}),/拒绝覆盖/);const item=await localItem(f,'target-hermes'),d=await f.manager.togglePreview({targetId:'target-hermes',itemId:item.id,enabled:false,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(d))).status,'matches_after');await fs.mkdir(f.hermesSkill,{mode:0o700});await fs.writeFile(join(f.hermesSkill,'SKILL.md'),'外部新增');assert.equal((await f.manager.check({id:d.token})).status,'changed');await assert.rejects(f.manager.rollbackPreview({id:d.token,revision:await f.revision()}),/拒绝覆盖/);});
test('持久化逆记录不能越界读取，伪造from/to在任何文件读取前阻断',async t=>{const f=await fixture(t),p=await f.publish();await f.manager.apply(confirm(p));const path=join(f.repository.directory,'agent-write-operations',p.token+'.json'),row=JSON.parse(await fs.readFile(path,'utf8'));row.to=join(f.base,'PRIVATE_NOT_ALLOWED');await fs.writeFile(path,JSON.stringify(row),{mode:0o600});let outsideReads=0;const filesystem=new Proxy(fs,{get(o,k){if(['lstat','open','readdir'].includes(k))return async(...args)=>{if(String(args[0]).includes('PRIVATE_NOT_ALLOWED')){outsideReads++;throw new Error('outside');}return o[k](...args);};return o[k];}});assert.equal((await f.recreate({filesystem}).check({id:p.token})).status,'unknown');assert.equal(outsideReads,0);await assert.rejects(f.manager.rollbackPreview({id:p.token,revision:await f.revision()}),/拒绝覆盖/);});
test('共享池链接/硬链/凭据包均不变；快照和手动接力不读会话不泄露完整配置',async t=>{const f=await fixture(t);await fs.symlink(f.from,join(f.homes.codex,'skills','linked'));const view=await f.manager.inspect({targetId:'target-codex'});assert.equal(view.items.find(i=>i.name==='linked').actionable,false);await fs.link(join(f.from,'SKILL.md'),join(f.base,'hardlink'));assert.equal((await f.manager.inspect({targetId:'target-codex'})).items.find(i=>i.name==='local-example').actionable,false);const bad=makeAsset({type:'Skill',title:'不支持包',files:[{path:'SKILL.md',text:true,data:'# 合成'},{path:'.env',text:true,data:'SYNTHETIC_PRIVATE'}]});await f.repository.updateAssets(a=>[...a,bad],{expectedRevision:await f.revision()});await assert.rejects(f.manager.publishPreview({targetId:'target-codex',assetId:bad.id,versionId:current(bad).id,revision:await f.revision()}),/凭据/);const snapshot=await f.manager.snapshot({targetId:'target-codex'});assert.equal(snapshot.sha256,digest(f.configText));assert.equal(JSON.stringify(snapshot).includes('SYNTHETIC_SECRET'),false);const relay=await f.manager.relay({sourceName:'Codex',targetName:'Hermes',goal:'合成目标',providedContext:'本人填入',nextStep:'先核验'});assert.equal(relay.readSessions,false);assert.equal(relay.sent,false);assert.ok(relay.content.includes('本人填入'));assert.equal(await fs.readFile(f.configPath,'utf8'),f.configText);});
test('停用journal保存失败时零目标目录写；prepared后失败不声称未开始',async t=>{let failPrepare=true,homePrefix='';const filesystem=new Proxy(fs,{get(o,k){if(k==='open')return async(...a)=>{if(failPrepare&&String(a[0]).includes('agent-write-operations')&&String(a[0]).endsWith('.tmp'))throw new Error('SYNTHETIC_IO_FAILURE');return o[k](...a);};if(k==='mkdir')return async(...a)=>{if(!failPrepare&&String(a[0])===homePrefix+'skills.disabled')throw new Error('SYNTHETIC_IO_FAILURE');return o[k](...a);};return o[k];}});const f=await fixture(t,{filesystem});homePrefix=f.homes.hermes+'/';const item=await localItem(f,'target-hermes');let p=await f.manager.togglePreview({targetId:'target-hermes',itemId:item.id,enabled:false,revision:await f.revision()});await assert.rejects(f.manager.apply(confirm(p)),e=>e.operationNotStarted===true&&!e.message.includes('SYNTHETIC_IO_FAILURE'));await assert.rejects(fs.lstat(join(f.homes.hermes,'skills.disabled')),{code:'ENOENT'});assert.ok(await fs.lstat(f.hermesSkill));failPrepare=false;p=await f.manager.togglePreview({targetId:'target-hermes',itemId:item.id,enabled:false,revision:await f.revision()});const result=await f.manager.apply(confirm(p));assert.equal(result.completedAt,null);assert.ok(result.notice);assert.equal(result.operationNotStarted,undefined);assert.ok(await fs.lstat(join(f.repository.directory,'agent-write-operations',p.token+'.json')));assert.equal((await f.manager.apply(confirm(p))).status,'matches_before');});
test('新包中途失败保留prepared与原文件，不能伪称成功；不递归删除半包',async t=>{let writes=0;const filesystem=new Proxy(fs,{get(o,k){if(k==='open')return async(...a)=>{if(String(a[0]).includes('/skills/published-example/')&&a[1]!==undefined&&(Number(a[1])&1)){writes++;if(writes===2)throw new Error('SYNTHETIC_PARTIAL_WRITE');}return o[k](...a);};return o[k];}});const f=await fixture(t,{filesystem}),p=await f.publish(),result=await f.manager.apply(confirm(p));assert.equal(result.completedAt,null);assert.notEqual(result.status,'matches_after');assert.ok(result.notice);assert.ok(await fs.lstat(join(f.repository.directory,'agent-write-operations',p.token+'.json')));assert.ok(await fs.lstat(join(f.homes.codex,'skills','published-example')));assert.equal(await fs.readFile(f.configPath,'utf8'),f.configText);await assert.rejects(f.manager.rollbackPreview({id:p.token,revision:await f.revision()}),/拒绝覆盖/);});
test('prepared存储期间开关或TTL变化：Codex配置/目录均不能继续写',async t=>{let mutate=()=>{};const filesystem=new Proxy(fs,{get(o,k){if(k==='rename')return async(from,to)=>{const result=await o[k](from,to);if(to.includes('/agent-content-config/')&&!to.endsWith('.receipt.json'))mutate();return result;};return o[k];}});const f=await fixture(t,{filesystem}),item=await pluginItem(f);let p=await f.manager.togglePreview({targetId:'target-codex',itemId:item.id,enabled:false,revision:await f.revision()});mutate=()=>f.advance(300001);let result=await f.manager.apply(confirm(p));assert.equal(result.status,'matches_before');assert.equal(result.completedAt,null);assert.equal(await fs.readFile(f.configPath,'utf8'),f.configText);p=await f.manager.togglePreview({targetId:'target-codex',itemId:item.id,enabled:false,revision:await f.revision()});mutate=()=>{f.setting.enabled=false;f.setting.generation++;};result=await f.manager.apply(confirm(p));assert.equal(result.status,'matches_before');assert.equal(await fs.readFile(f.configPath,'utf8'),f.configText);});
test('发布父目录被链接替换：检测已创建目录身份，外部目录零新文件',async t=>{let root='',outside='',injected=false;const filesystem=new Proxy(fs,{get(o,k){if(k==='mkdir')return async(path,...rest)=>{const result=await o[k](path,...rest);if(path===root+'/assets'&&!injected){injected=true;await fs.rename(path,root+'/assets-old');await fs.symlink(outside,path);}return result;};return o[k];}});const f=await fixture(t,{filesystem});root=join(f.homes.codex,'skills','published-example');outside=join(f.base,'outside');await fs.mkdir(outside,{mode:0o700});const p=await f.publish(),r=await f.manager.apply(confirm(p));assert.notEqual(r.status,'matches_after');assert.equal(r.completedAt,null);assert.deepEqual(await fs.readdir(outside),[]);assert.equal(await fs.readFile(f.configPath,'utf8'),f.configText);});
test('未知原权限生成安全权限；明示组/其他可写权限拒绝而不改权限',async t=>{const f=await fixture(t),safe=makeAsset({type:'Skill',title:'未知权限合成',files:[{path:'SKILL.md',text:true,data:'---\nname: unknown-permissions\n---\n# 合成'},{path:'nested/file.bin',text:false,data:new Uint8Array([5])}]}),bad=makeAsset({type:'Skill',title:'明示不支持权限',files:[{path:'SKILL.md',text:true,data:'# 合成',mode:0o666}]});await f.repository.updateAssets(a=>[...a,safe,bad],{expectedRevision:await f.revision()});const p=await f.manager.publishPreview({targetId:'target-codex',assetId:safe.id,versionId:current(safe).id,revision:await f.revision()});assert.equal(p.changes.find(c=>c.path==='SKILL.md').mode,0o600);assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');assert.equal((await fs.stat(join(f.homes.codex,'skills','unknown-permissions','nested','file.bin'))).mode&0o777,0o600);assert.equal((await fs.stat(join(f.homes.codex,'skills','unknown-permissions','nested'))).mode&0o777,0o700);await assert.rejects(f.manager.publishPreview({targetId:'target-codex',assetId:bad.id,versionId:current(bad).id,revision:await f.revision()}),/不静默改权限/);});
test('同Agent两目标显示字段真实等价迁移与局部回滚，源配置漂移阻止写',async t=>{const f=await fixture(t),secondHome=join(f.base,'中文目标二');await fs.mkdir(secondHome,{mode:0o700});const secondConfig=join(secondHome,'config.toml'),before='# 原中文\napi_key="SYNTHETIC_SECOND_SECRET"\n[tui]\nanimations = false # keep\n';await fs.writeFile(secondConfig,before,{mode:0o600});const target={...f.targets[0],id:'target-codex-second',bindingId:'binding-second',home:{id:'home-second',path:secondHome,label:'合成Home二'}};await f.repository.updateConnections(c=>({...c,agentTargets:[...c.agentTargets,target]}));const original=f.adapters.inspectAgentInventory;f.adapters.inspectAgentInventory=async id=>{const value=await original(id);if(id==='codex')value.homes.push({id:'home-second',path:secondHome,source:'合成独立目录',status:'present',errors:[],identity:homeIdentity(await fs.lstat(secondHome))});return value;};let p=await f.manager.configMigrationPreview({sourceTargetId:'target-codex',targetId:target.id,key:'tui.animations',revision:await f.revision()});assert.equal(p.changes[0].beforeValue,false);assert.equal(p.changes[0].afterValue,true);assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');assert.equal(await fs.readFile(secondConfig,'utf8'),before.replace('animations = false','animations = true'));assert.equal(await fs.readFile(f.configPath,'utf8'),f.configText);const undo=await f.manager.rollbackPreview({id:p.token,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(undo))).status,'matches_after');assert.equal(await fs.readFile(secondConfig,'utf8'),before);const records=await fs.readdir(join(f.repository.directory,'agent-content-config'));for(const name of records)assert.equal((await fs.readFile(join(f.repository.directory,'agent-content-config',name),'utf8')).includes('SYNTHETIC_SECOND_SECRET'),false);p=await f.manager.configMigrationPreview({sourceTargetId:'target-codex',targetId:target.id,key:'tui.animations',revision:await f.revision()});await fs.appendFile(f.configPath,'# 源改动\n');await assert.rejects(f.manager.apply(confirm(p)),/迁移源显示配置已变化/);assert.equal(await fs.readFile(secondConfig,'utf8'),before);});
test('含危险布局的插件不开放写入；未知启用值诚实展示而不是猜默认',async t=>{const f=await fixture(t);await fs.writeFile(f.configPath,'[plugins."review@synthetic"]\nenabled="unknown"\n',{mode:0o600});let view=await f.manager.inspect({targetId:'target-codex'}),item=view.items.find(i=>i.type==='Plugin');assert.equal(item.enabled,null);assert.equal(item.actionable,false);await assert.rejects(f.manager.togglePreview({targetId:'target-codex',itemId:item.id,enabled:false,revision:await f.revision()}),/布局|类型/);await fs.writeFile(f.configPath,'[plugins."review@synthetic"]\n# 尚无明确状态\n',{mode:0o600});view=await f.manager.inspect({targetId:'target-codex'});item=view.items.find(i=>i.type==='Plugin');assert.equal(item.enabled,null);const before=await fs.readFile(f.configPath,'utf8'),p=await f.manager.togglePreview({targetId:'target-codex',itemId:item.id,enabled:true,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(p))).status,'matches_after');const undo=await f.manager.rollbackPreview({id:p.token,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(undo))).status,'matches_after');assert.equal(await fs.readFile(f.configPath,'utf8'),before);});
test('配置逆记录越界ref不读目标外文件；发现错误不得暴露adapter私密错误',async t=>{const f=await fixture(t),item=await localItem(f),p=await f.manager.togglePreview({targetId:'target-codex',itemId:item.id,enabled:false,revision:await f.revision()});await f.manager.apply(confirm(p));const path=join(f.repository.directory,'agent-content-config',p.token+'.json'),row=JSON.parse(await fs.readFile(path,'utf8'));row.ref=join(f.base,'outside','SKILL.md');await fs.writeFile(path,JSON.stringify(row),{mode:0o600});assert.equal((await f.manager.check({id:p.token})).status,'unknown');await assert.rejects(f.manager.rollbackPreview({id:p.token,revision:await f.revision()}),/固定目标范围/);f.adapters.inspectAgentInventory=async()=>{throw Object.assign(new Error('PRIVATE_SCOPE_SENTINEL'),{status:409});};await assert.rejects(f.manager.inspect({targetId:'target-codex'}),e=>e.status===503&&!e.message.includes('PRIVATE_SCOPE_SENTINEL'));});

