// 派单173追加：原断言不改，新增引用媒体完整发布/预览固定字节/回滚/篡改拒绝。
test('逆向Skill引用媒体随固定预览复制到合成Agent：字节SHA/mode回读；缺图拒绝残包',async t=>{
 const f=await fixture(t);const {createReverseMedia}=await import('../server/reverse-media.mjs');const {generateRecipeSkill}=await import('./helpers/reverse-skill.js');const {createSpecimen,prepareReplica,confirmReplica}=await import('../src/reverse-recipe.js');const {fixtureRecipe}=await import('./reverse-v16-fixture.mjs');const media=createReverseMedia(await fs.realpath(f.repository.directory));const bytes=new Uint8Array(await fs.readFile(new URL('./fixtures/reverse-v16/reverse-0.png',import.meta.url))),m=await media.store({data:bytes});let r=createSpecimen({type:'IMG',title:'合成发布图',media:[m]});r.recipe=fixtureRecipe('IMG');r=confirmReplica(r,{...prepareReplica(r,{media:[m]}),scores:{composition:5,color:5,font:5,texture:5}});const a=makeAsset({...generateRecipeSkill(r),type:'Skill'});await f.repository.updateAssets(v=>[...v,a],{expectedRevision:await f.revision()});const p=await f.manager.publishPreview({targetId:'target-codex',assetId:a.id,versionId:current(a).id,revision:await f.revision()});assert.ok(p.changes.some(c=>c.path==='assets/reference-01.png'&&c.size===bytes.length));await fs.writeFile(join(f.repository.directory,m.path),'SYNTHETIC_CHANGED',{mode:0o600});assert.equal((await f.manager.apply(confirm(p))).status,'matches_after','确认使用核验过的固定预览字节，不偷换实体');const to=join(f.homes.codex,'skills','reverse-'+r.id.toLowerCase().replace(/[^a-z0-9-]/g,'').slice(0,55));assert.equal(digest(await fs.readFile(join(to,'assets','reference-01.png'))),m.sha256);assert.equal((await fs.stat(join(to,'assets','reference-01.png'))).mode&0o777,0o600);const rollback=await f.manager.rollbackPreview({id:p.token,revision:await f.revision()});assert.equal((await f.manager.apply(confirm(rollback))).status,'matches_after');await assert.rejects(f.manager.publishPreview({targetId:'target-codex',assetId:a.id,versionId:current(a).id,revision:await f.revision()}),/SHA|大小|格式|媒体/);assert.deepEqual((await f.repository.read()).assets.find(x=>x.id===a.id).versions[0].mediaManifest,current(a).mediaManifest);
});

