test('白名单快照可持久回读/重启历史/完整备份；重复UUID不重写、不带正文凭据',async t=>{
 const f=await fixture(t,{enabled:false}),view=await f.manager.snapshot({targetId:'target-codex'}),input={targetId:'target-codex',revision:view.revision,sourceSha256:view.sha256,sourceIdentity:view.sourceIdentity,operationId:'00000000-0000-4000-8000-000000000262'};
 const saved=await f.manager.snapshotSave(input);assert.equal(saved.status,'saved');assert.equal(saved.adoption,'unverified');assert.deepEqual(saved.fields.map(x=>x.key),['tui.animations','tui.show_tooltips']);assert.equal(saved.fields[0].value,true);assert.equal(saved.fields[1].value,null);
 const file=join(f.repository.directory,'agent-config-snapshots',input.operationId+'.json'),before=await fs.stat(file),text=await fs.readFile(file,'utf8');assert.equal(before.mode&0o777,0o600);assert.equal(text.includes('SYNTHETIC_SECRET'),false);assert.equal(text.includes(f.homes.codex),false);assert.equal(text.includes('label'),false);
 assert.deepEqual(await f.manager.snapshotSave(input),saved);assert.equal((await fs.stat(file)).mtimeMs,before.mtimeMs);assert.deepEqual(await f.recreate().snapshotRead({id:input.operationId}),saved);assert.equal((await f.recreate().snapshotHistory({targetId:'target-codex'})).items.length,1);
 const {packDirectory}=await import('../server/full-backup.mjs');const backup=await packDirectory(f.repository.directory);assert.ok(backup.manifest.files.some(x=>x.path==='agent-config-snapshots/'+input.operationId+'.json'));assert.equal(await fs.readFile(f.configPath,'utf8'),f.configText);
});
